inputs = ['udfx', 'xijx', 'ixaz', 'wh', 'bk']
outputs = ['udgjkw', 'jkwijjkw', 'ijkwaz', 'wh', 'bfhc']

# Let's compare character by character to find patterns
for i, inp in enumerate(inputs):
    print(f"Input: {inp} -> Output: {outputs[i]}")
    # Show differences
    out = outputs[i]
    for j, char in enumerate(inp):
        if j < len(out) and char != out[j]:
            print(f"  Position {j}: '{char}' -> '{out[j]}'")
    if len(inp) < len(out):
        print(f"  Extra chars in output: '{out[len(inp):]}'")
    elif len(inp) > len(out):
        print(f"  Missing chars in output: '{inp[len(out):]}'")

